/* Starry Night Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="starry-night-light"] {
  --background: #f8f8f8;
  --foreground: #1c2338;
  --card: #e3e8ee;
  --card-foreground: #1c2338;
  --popover: #fffcee;
  --popover-foreground: #1c2338;
  --primary: #395aa1;
  --primary-foreground: #fffcee;
  --secondary: #f9c970;
  --secondary-foreground: #1c2338;
  --muted: #e5e5de;
  --muted-foreground: #395aa1;
  --accent: #6fa3c0;
  --accent-foreground: #fffcee;
  --destructive: #2d1d2f;
  --destructive-foreground: #fffcee;
  --border: #aeb9c4;
  --input: #6fa3c0;
  --ring: #f9c970;
  --chart-1: #395aa1;
  --chart-2: #f9c970;
  --chart-3: #6fa3c0;
  --chart-4: #aeb9c4;
  --chart-5: #2d1d2f;
  --radius: 0.5rem;
  --sidebar: #e3e8ee;
  --sidebar-foreground: #1c2338;
  --sidebar-primary: #395aa1;
  --sidebar-primary-foreground: #fffcee;
  --sidebar-accent: #f9c970;
  --sidebar-accent-foreground: #1c2338;
  --sidebar-border: #aeb9c4;
  --sidebar-ring: #f9c970;
  --font-sans: Libre Baskerville, serif;
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono:
    ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
    "Courier New", monospace;
  --shadow-color: #000000;
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

/* Dark mode */
