  --popover-foreground: #fee06b;
  --primary: #395aa1;
  --primary-foreground: #fee06b;
  --secondary: #fee06b;
  --secondary-foreground: #23243a;
  --muted: #23243a;
  --muted-foreground: #79879f;
  --accent: #beceef;
  --accent-foreground: #181a24;
  --destructive: #a14b6d;
  --destructive-foreground: #fee06b;
  --border: #2e2f3f;
  --input: #395aa1;
  --ring: #fee06b;
  --chart-1: #395aa1;
  --chart-2: #fee06b;
  --chart-3: #6fa3c0;
  --chart-4: #79879f;
  --chart-5: #a14b6d;
  --radius: 0.5rem;
  --sidebar: #23243a;
  --sidebar-foreground: #e8ebf2;
  --sidebar-primary: #395aa1;
  --sidebar-primary-foreground: #fee06b;
  --sidebar-accent: #fee06b;
  --sidebar-accent-foreground: #23243a;
  --sidebar-border: #2e2f3f;
  --sidebar-ring: #fee06b;
  --font-sans: Libre Baskerville, serif;
